/* [Velt] Place Velt UI customization styles here */

/* Velt Comment Text Styling */
velt-comment-text[comment-available="true"] {
  background-color: rgba(255, 208, 0, 0.3);
  border-radius: 2px;
  padding: 2px 0;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

velt-comment-text[comment-available="true"]:hover {
  background-color: rgba(255, 208, 0, 0.4);
}

/* Theme Configuration - Based on Figma Design */
:root {
  /* Typography */
  --velt-default-font-family: Poppins;

  /* Border Radius */
  --velt-border-radius-2xs: 0.061rem; /* 0.972px */
  --velt-border-radius-xs: 0.125rem; /* 2px */
  --velt-border-radius-sm: 0.375rem; /* 6px */
  --velt-border-radius-md: 0.750rem; /* 12px */
  --velt-border-radius-lg: 1.000rem; /* 16px */
  --velt-border-radius-xl: 1.167rem; /* 18.667px - circular buttons */
  --velt-border-radius-2xl: 1.500rem; /* 24px - pill shape */
  --velt-border-radius-3xl: 2.000rem; /* 32px */
  --velt-border-radius-full: 5.000rem; /* 80px */

  /* Light Mode */
  /* Accent Colors */
  --velt-light-mode-accent: #141414;
  --velt-light-mode-accent-text: #ffffff;
  --velt-light-mode-accent-hover: #000000;
  --velt-light-mode-accent-foreground: #ffffff;
  --velt-light-mode-accent-light: #1f1f1f;
  --velt-light-mode-accent-transparent: rgba(20, 20, 20, 0.08);

  /* Background Shades */
